  async add_bill(a, ctx) { const ex = ctx.of('entry').find(x => x.hub === 'Finances' && x.tool === 'bills' && String(x.f.what || '').toLowerCase() === String(a.what).toLowerCase()); const r = ex ? clone(ex) : { id: newId('e'), kind: 'entry', hub: 'Finances', tool: 'bills', f: { what: a.what, pay: 'Pay by hand', day: 1, acct: '' } }; guard(ctx, r, 'change bills'); if (a.amount != null) { if (r.f.amount && +r.f.amount !== +a.amount) r.f.amtH = [...(r.f.amtH || []), +r.f.amount].slice(-12); r.f.amount = +a.amount; } if (a.day) r.f.day = Math.max(1, Math.min(31, Math.round(a.day))); if (a.autopay != null) r.f.pay = a.autopay ? 'Autopay' : 'Pay by hand'; if (a.source) r.source = a.source; await write(ctx, r, `${ex ? 'Updated' : 'Added'} the ${a.what} bill`, !ex); return { ok: true, id: r.id, updated_existing: !!ex }; },
  async save_review(a, ctx) { const per = a.period || 'week', ws = weekStart(ctx.today), wk = per === 'week' ? (monIdx(ctx.today) >= 4 ? ws : addK(ws, -7)) : ctx.today.slice(0, 8) + '01'; const rec = { id: newId('r'), kind: 'review', period: per, week: wk, wins: a.wins || '', blocks: a.blocks || '', next: a.next || '', answers: {}, title: `Week of ${wk}`, via: 'claude' }; guard(ctx, rec, 'save reviews'); await write(ctx, rec, `Saved your ${per}ly review`, true); const nx = addK(ws, 7); for (const t of (a.top3_next_week || []).slice(0, 3)) await H.add_task({ title: t, date: nx, priority: 'high' }, ctx); return { ok: true, id: rec.id }; },
  async propose_changes(a, ctx) { const did = []; ctx.proposeAll = true; ctx.propSummary = String(a.summary || '').slice(0, 300); try { for (const c of (a.changes || []).slice(0, 40)) { const f = H[c.tool] || H2[c.tool]; if (!f || /^(get_|find|list_|export_|undo|propose)/.test(c.tool)) { did.push(`skipped ${c.tool}`); continue; } try { await f(c.arguments || {}, ctx); did.push(c.tool); } catch (e) { did.push(`${c.tool}: ${e.user ? e.message : 'failed'}`); } } } finally { ctx.proposeAll = true; } return { ok: true, proposed: did.length, steps: did }; },
