async function tokenUser(db, req) {
  const tok = String(req.headers.authorization || '').replace(/^Bearer\s+/i, ''); if (!tok || tok.length < 20) return null;
  const { data } = await db.from('records').select('user_id,data').eq('id', 'mcptok_' + sha(tok)).eq('deleted', false).limit(1);
  const r = data && data[0]; if (!r || !r.data || (r.data.exp && r.data.exp < Date.now())) return null;
  if (!r.data.seen || Date.now() - r.data.seen > 36e5) db.from('records').update({ data: Object.assign({}, r.data, { seen: Date.now() }) }).eq('user_id', r.user_id).eq('id', 'mcptok_' + sha(tok)).then(() => {}, () => {});
  return { uid: r.user_id, client: r.data.name || 'Claude' };
}

